record User { name: String, age: Int64 }

fn label(u: User) -> String {
    return u.name
}

fn older(u: User) -> User {
    return User { age: u.age + 1 with &u }
}

pub type AppError = Failed(String)

pub fn main() -> Result<(), AppError> {
    let u = User { name: "a", age: 1 }
    let v = older(u)
    return Ok(())
}

